=Analyse cet article et réponds UNIQUEMENT avec un JSON valide (sans markdown, sans balises) :

Titre : {{$json.title}}
Description : {{$json.description}}
Source : {{$json.source}}

Réponds au format :
{"resume": "résumé en 2-3 phrases", "tags": ["tag1", "tag2"], "priorite": "Haute|Moyenne|Basse"}

Tags possibles : IA, Meal Planning, Startup, Tech, Marketing

Priorité :
- Haute : concurrent, innovation majeure, réglementation
- Moyenne : tendance intéressante
- Basse : info générale

parameters.jsCode:
const items = $input.all();
const originals = $('Filtre doublons1').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const orig = originals[i]?.json || {};
  try {
    let text = items[i].json.output || items[i].json.text || '';
    text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    text = text.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');

    const analysis = JSON.parse(text);

    // Convert pubDate to ISO 8601
    let dateStr = orig.pubDate || '';
    if (dateStr) {
      try {
        const d = new Date(dateStr);
        if (!isNaN(d.getTime())) dateStr = d.toISOString().split('T')[0];
      } catch { dateStr = null; }
    }

    // Tags: array to comma-separated string
    const tags = Array.isArray(analysis.tags) ? analysis.tags.join(',') : '';

    results.push({
      json: {
        title: orig.title || '',
        link: orig.link || '',
        source: orig.source || '',
        pubDate: dateStr,
        description: orig.description || '',
        resume: analysis.resume || analysis.r\u00e9sum\u00e9 || '',
        tags: tags,
        priorite: analysis.priorite || analysis.priorit\u00e9 || 'Moyenne'
      }
    });
  } catch (e) {
    // On error, use original data with fallback summary
    let dateStr = orig.pubDate || '';
    if (dateStr) {
      try {
        const d = new Date(dateStr);
        if (!isNaN(d.getTime())) dateStr = d.toISOString().split('T')[0];
      } catch { dateStr = null; }
    }
    results.push({
      json: {
        title: orig.title || '',
        link: orig.link || '',
        source: orig.source || '',
        pubDate: dateStr,
        description: orig.description || '',
        resume: (orig.description || '').substring(0, 200),
        tags: '',
        priorite: 'Moyenne'
      }
    });
  }
}

return results;

