if (!staticData.processedUrls) staticData.processedUrls = {};

// Nettoyage entrées > 7 jours
var sevenDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
Object.keys(staticData.processedUrls).forEach(function(url) {
  if (staticData.processedUrls[url] < sevenDaysAgo) delete staticData.processedUrls[url];
});

