var results = [];

for (var i = 0; i < items.length; i++) {
  var link = (items[i].json.link || '').trim();
  if (!link || items[i].json._empty) continue;
  if (staticData.processedUrls[link]) continue; // déjà traité
  results.push(items[i]);
}

return results.length > 0 ? results : [{ json: { _empty: true } }];

